 const oldProp=document.getElementById('leg-preview');
 if(e.target.id==='leg-league'||!oldProp||!isNflPlayerMarket(market))state.lookup.chosen=null;
 if(e.target.id==='leg-league'){document.getElementById('leg-selection').value='';state.lookup.selectedTeam=null;state.lookup.roster=[];state.lookup.request++;state.lookup.league=league;state.lookup.query='';}drawLookup();document.getElementById('prop-controls')?.remove();const box=document.createElement('div');box.innerHTML=propFields(league,market);document.getElementById('leg-market').closest('.form-item').insertAdjacentElement('afterend',box.firstElementChild);const form=document.getElementById('leg-form');const control=document.getElementById('prop-line');const notes=document.getElementById('leg-notes');
